         ["\\( \\sigma_A = \\sigma_B \\)", "\\( \\sigma_A = 2\\sigma_B \\)", "\\( \\sigma_A = 4\\sigma_B \\)", "\\( \\sigma_B > \\sigma_A \\)"], 1,
